/**
 * Naya Raipur service-area data — GENERATED by scripts/generate-sectors-seed.mjs,
 * do not hand-edit. Mirrors the public.sectors seed (migration 020) so the
 * storefront can show ETAs and render /delivery/<sector> pages without a DB
 * round-trip. Distances are straight-line from the Sector 27 dark store.
 */

export interface Eta {
  min: number;
  max: number;
  zone: string;
}

export interface SectorArea {
  slug: string;
  name: string;
  nameHi: string;
  pincode: string;
  /** Pincode is the nearest serviceable one, not India Post verified. */
  pincodeApprox: boolean;
  areaType: "residential" | "civic" | "campus";
  lat: number;
  lng: number;
  /** Straight-line metres from the dark store. */
  distanceM: number;
  eta: Eta;
  /** false = mapped but not yet serviceable ("coming soon"). */
  active: boolean;
}

