export const ACTIVE_SECTOR_AREAS = SECTOR_AREAS.filter((s) => s.active);

export function findSectorArea(nameOrSlug: string): SectorArea | undefined {
  const key = nameOrSlug.toLowerCase().trim();
  return SECTOR_AREAS.find((s) => s.slug === key || s.name.toLowerCase() === key);
}

